<script setup>
import {onMounted,reactive,ref,computed} from 'vue'
import {RouterLink} from 'vue-router'
import {ensureInstructor} from '../lib/instructor'
import {authRequest,notify,state} from '../lib/state'
import {accentHex,accentNames,fontStacks,fontNames,layoutNames,linkNames,styleQuiz,studioColor} from '../lib/studio'
import OwnerTabs from '../components/OwnerTabs.vue'
const busy=ref(false),quiz=ref(''),galleryUrl=ref(''),coverUrl=ref('')
function useCoverUrl(){const u=coverUrl.value.trim();if(!/^https:\/\/\S+$/i.test(u))return notify('El enlace debe empezar con https://');form.coverImage=u;coverUrl.value=''}
function uploadCover(e){const f=e.target.files?.[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>1_100_000)return notify('Usa JPG, PNG o WebP de hasta 1 MB.');const r=new FileReader();r.onload=()=>{form.coverImage=String(r.result)};r.readAsDataURL(f)}
const form=reactive({displayName:'',tagline:'',bio:'',accent:'terracota',accentColor:'',font:'moderna',layout:'portada',coverImage:'',gallery:[],district:'',address:'',links:{web:'',instagram:'',facebook:'',tiktok:'',whatsapp:''}})
onMounted(async()=>{try{await ensureInstructor();const s=state.user?.studio||{};Object.assign(form,{...s,links:{...form.links,...(s.links||{}),...(s.link&&!s.links?.web?{web:s.link}:{})},gallery:[...(s.gallery||[])]})}catch(e){notify(e.message)}})
function applyQuiz(option){quiz.value=option.id;Object.assign(form,option.set,{accentColor:''});notify(`Estilo "${option.label}" aplicado. Puedes ajustar cada detalle.`)}
function addGallery(src){if(form.gallery.length>=6)return notify('Máximo 6 imágenes en la galería.');if(!form.gallery.includes(src))form.gallery.push(src)}
function addGalleryUrl(){const u=galleryUrl.value.trim();if(!/^https:\/\/\S+$/i.test(u))return notify('El enlace debe empezar con https://');addGallery(u);galleryUrl.value=''}
const color=computed(()=>studioColor(form))
async function save(){try{busy.value=true;const links=Object.fromEntries(Object.entries(form.links).filter(([,v])=>v.trim()));const res=await authRequest('/instructor/studio',{method:'PATCH',body:{...form,links}});state.user.studio=res.item;notify('Perfil público actualizado.')}catch(e){notify(e.message)}finally{busy.value=false}}
</script>
<template><div class="page owner-page"><div class="page-heading"><div><div class="eyebrow earth">IDENTIDAD DEL TALLERISTA</div><h1>Personalizar mi perfil</h1><p class="muted">Tú decides la estética de tu página: colores, tipografía, distribución, textos, fotos y enlaces.</p></div><RouterLink v-if="state.user" :to="`/estudio/${state.user.id}`" class="btn outline">Ver mi página pública</RouterLink></div><OwnerTabs/>
<section class="form-card"><h2>1. ¿Qué estética quieres para tu taller?</h2><p class="small muted">Elige la opción que más se parezca a tu propuesta; luego ajusta todo a tu gusto o personalízalo por completo en el paso 2.</p><div class="quiz-grid"><button v-for="o in styleQuiz" :key="o.id" type="button" class="quiz-option" :class="{selected:quiz===o.id}" :style="{borderColor:accentHex[o.set.accent],fontFamily:fontStacks[o.set.font]}" @click="applyQuiz(o)"><b>{{o.label}}</b><small>{{o.hint}}</small></button></div></section>
<form class="studio-layout" @submit.prevent="save"><section class="form-card"><h2>2. Personalización</h2><div class="form-grid">
<label>Nombre del estudio<input v-model.trim="form.displayName" maxlength="90" placeholder="Ej. Estudio Meza"/></label><label>Frase corta<input v-model.trim="form.tagline" maxlength="140" placeholder="Ej. Cerámica en torno frente al mar"/></label>
<label class="span-all">Descripción del tallerista<textarea v-model.trim="form.bio" maxlength="900" rows="4" placeholder="Tu experiencia, estilo y lo que hace único a tu taller..."/></label>
<label>Color principal<select v-model="form.accent" @change="form.accentColor=''"><option v-for="(name,k) in accentNames" :key="k" :value="k">{{name}}</option></select></label>
<label>Color propio (opcional)<span class="color-row"><input type="color" :value="form.accentColor||accentHex[form.accent]" @input="form.accentColor=$event.target.value" aria-label="Elegir color"/><button v-if="form.accentColor" type="button" class="btn ghost sm" @click="form.accentColor=''">Quitar</button></span></label>
<label>Tipografía<select v-model="form.font"><option v-for="(name,k) in fontNames" :key="k" :value="k">{{name}}</option></select></label>
<label>Distribución de la página<select v-model="form.layout"><option v-for="(name,k) in layoutNames" :key="k" :value="k">{{name}}</option></select></label>
<label>Distrito del estudio<select v-model="form.district"><option value="">Sin indicar</option><option v-for="d in state.meta.districts" :key="d">{{d}}</option></select></label><label>Dirección del estudio<input v-model.trim="form.address" maxlength="160" placeholder="Calle y número"/></label>
<div class="span-all"><b>Enlaces (HTTPS)</b><div class="form-grid links-grid"><label v-for="(name,k) in linkNames" :key="k">{{name}}<input v-model.trim="form.links[k]" type="url" pattern="https://.*" maxlength="220" :placeholder="k==='whatsapp'?'https://wa.me/51999999999':'https://…'"/></label></div></div>
<label class="span-all">Imagen de portada<select v-model="form.coverImage"><option value="">Sin portada</option><option v-for="img in state.meta.images" :key="img" :value="img">{{img.split('/').at(-1)}}</option><option v-if="form.coverImage && !state.meta.images.includes(form.coverImage)" :value="form.coverImage">Foto propia</option></select><span class="color-row"><input v-model="coverUrl" type="url" placeholder="https://… foto de portada propia" aria-label="Enlace de portada"/><button type="button" class="btn outline sm" @click="useCoverUrl">Usar enlace</button><label class="btn light sm">Subir archivo<input type="file" accept="image/png,image/jpeg,image/webp" hidden @change="uploadCover"/></label></span></label>
<div class="span-all"><b>Galería (hasta 6)</b><div class="photo-choices"><button v-for="img in state.meta.images" type="button" :key="img" :class="{selected:form.gallery.includes(img)}" @click="form.gallery.includes(img)?form.gallery.splice(form.gallery.indexOf(img),1):addGallery(img)"><img :src="img" alt=""/></button></div><div class="color-row"><input v-model="galleryUrl" type="url" placeholder="https://… foto propia" aria-label="Enlace de foto de galería"/><button type="button" class="btn outline sm" @click="addGalleryUrl">Añadir</button></div><p class="small muted">{{form.gallery.length}} imagen(es) seleccionadas.</p></div>
<p class="span-all small muted">Por seguridad no se ejecuta HTML ni CSS libre: cada opción se valida en el servidor.</p><button class="btn primary" :disabled="busy">{{busy?'Guardando...':'Guardar perfil público'}}</button></div></section>
<aside class="form-card preview" :style="{fontFamily:fontStacks[form.font],borderTop:`8px solid ${color}`}"><small class="muted">Vista previa</small><img v-if="form.coverImage && form.layout!=='compacta'" :src="form.coverImage" alt="" class="photo-preview"/><h2 :style="{color}">{{form.displayName||state.user?.name}}</h2><p v-if="form.tagline"><i>{{form.tagline}}</i></p><p class="muted">{{form.bio||'Descripción del tallerista'}}</p><div class="mini-gallery"><img v-for="g in form.gallery.slice(0,3)" :key="g" :src="g" alt=""/></div><span v-for="(v,k) in form.links" :key="k" v-show="v" class="tag" :style="{background:color,color:'#fff',marginRight:'6px'}">{{linkNames[k]}}</span></aside></form></div></template>
<style scoped>.quiz-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin-top:12px}.quiz-option{display:grid;gap:4px;text-align:left;padding:14px;border:2px solid;border-radius:14px;background:#fff;cursor:pointer}.quiz-option.selected{box-shadow:0 0 0 3px #f1d7c6;background:#fffaf5}.studio-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:18px;align-items:start;margin-top:18px}.preview{position:sticky;top:90px}.color-row{display:flex;gap:8px;align-items:center}.color-row input[type=url]{flex:1;padding:9px;border:1px solid #dfcbb5;border-radius:10px}.links-grid{margin-top:8px}.mini-gallery{display:flex;gap:6px;margin:8px 0}.mini-gallery img{width:31%;aspect-ratio:1;object-fit:cover;border-radius:8px}@media (max-width:860px){.studio-layout{grid-template-columns:1fr}.preview{position:static}}</style>
